    12	 */
    13	export default function inspect(value: mixed): string {
    14	  switch (typeof value) {
    15	    case 'string':
    16	      return JSON.stringify(value);
    17	    case 'function':
    18	      return value.name ? `[function ${value.name}]` : '[function]';
    19	    case 'object':
    20	      if (value) {
    21	        if (typeof value.inspect === 'function') {
    22	          return value.inspect();
    23	        } else if (Array.isArray(value)) {
    24	          return '[' + value.map(inspect).join(', ') + ']';
    25	        }
    26	
    27	        const properties = Object.keys(value)
    28	          .map(k => `${k}: ${inspect(value[k])}`)
    29	          .join(', ');
    30	        return properties ? '{ ' + properties + ' }' : '{}';
    31	      }
    32	      return String(value);
    33	    default:
    34	      return String(value);
    35	  }
    36	}
