    50	 */
    51	function fixIndent(str: string): string {
    52	  const trimmedStr = str
    53	    .replace(/^\n*/m, '') //  remove leading newline
    54	    .replace(/[ \t]*$/, ''); // remove trailing spaces and tabs
    55	  const indentMatch = /^[ \t]*/.exec(trimmedStr);
    56	  invariant(Array.isArray(indentMatch));
    57	  const indent = indentMatch[0]; // figure out indent
    58	  return trimmedStr.replace(RegExp('^' + indent, 'mg'), ''); // remove indent
    59	}
