    63	 * and trailing spaces and tabs, but keeps trailing newlines.
    64	 *
    65	 * Example usage:
    66	 * const str = dedent`
    67	 *   {
    68	 *     test
    69	 *   }
    70	 * `;
    71	 * str === "{\n  test\n}\n";
    72	 */
    73	export default function dedent(
    74	  strings: string | Array<string>,
    75	  ...values: Array<string>
    76	): string {
    77	  // when used as an ordinary function, allow passing a singleton string
    78	  const strArray = typeof strings === 'string' ? [strings] : strings;
    79	  const numValues = values.length;
    80	
    81	  const str = strArray.reduce((prev, cur, index) => {
    82	    let next = prev + cur;
    83	    if (index < numValues) {
    84	      next += values[index]; // interpolation
    85	    }
    86	    return next;
    87	  }, '');
